import hashlib, hmac
SECRET = b'test-secret-only'
def sign(payload):
    return hmac.new(SECRET, payload.encode(), hashlib.sha256).hexdigest()
EVENTS = [('evt-1', 'payment completed', sign('payment completed'), False), ('evt-2', 'payment completed', 'deadbeef', False), ('evt-1', 'payment completed', sign('payment completed'), True)]
for eid, payload, sig, replay in EVENTS:
    if sig != sign(payload):
        print(eid, '-> REJECTED (bad signature)')
    elif replay:
        print(eid, '-> ACKNOWLEDGED, NOT REPROCESSED (replay)')
    else:
        print(eid, '-> VERIFIED, PROCESSED:', payload)

